class WeatherSystem{constructor(){this.currentTime="day",this.currentWeather="clear",this.autoCycle=!1,this.cycleInterval=null,this.particleCount={rain:100,snow:50,stars:100},this.init()}init(){const t=document.getElementById("mapContainer");if(!t)return;t.insertAdjacentHTML("afterbegin",'\n            <div class="atmospheric-overlay"></div>\n            <div class="stars-container"></div>\n            <div class="fog-container">\n                <div class="fog-layer"></div>\n                <div class="fog-layer"></div>\n            </div>\n            <div class="rain-container"></div>\n            <div class="snow-container"></div>\n        '),this.createControls(),this.generateStars(),this.generateRain(),this.generateSnow(),this.setTimeFromRealWorld(),console.log("🌤️ Weather System initialized")}createControls(){document.getElementById("mapContainer").insertAdjacentHTML("beforeend",'\n            <div class="weather-controls" id="weatherControls">\n                <div class="weather-control-title">\n                    <i class="fas fa-cloud-sun"></i>\n                    Atmosphere\n                </div>\n                \n                <div class="weather-option-group">\n                    <div class="weather-option-label">Time of Day</div>\n                    <div class="weather-btn-group">\n                        <button class="weather-btn time-btn" data-time="dawn">\n                            🌅 Dawn\n                        </button>\n                        <button class="weather-btn time-btn active" data-time="day">\n                            ☀️ Day\n                        </button>\n                        <button class="weather-btn time-btn" data-time="dusk">\n                            🌇 Dusk\n                        </button>\n                        <button class="weather-btn time-btn" data-time="night">\n                            🌙 Night\n                        </button>\n                    </div>\n                </div>\n\n                <div class="weather-option-group">\n                    <div class="weather-option-label">Weather</div>\n                    <div class="weather-btn-group">\n                        <button class="weather-btn weather-type-btn active" data-weather="clear">\n                            ☀️ Clear\n                        </button>\n                        <button class="weather-btn weather-type-btn" data-weather="rain">\n                            🌧️ Rain\n                        </button>\n                        <button class="weather-btn weather-type-btn" data-weather="snow">\n                            ❄️ Snow\n                        </button>\n                        <button class="weather-btn weather-type-btn" data-weather="fog">\n                            🌫️ Fog\n                        </button>\n                    </div>\n                </div>\n\n                <div class="auto-cycle-toggle" id="autoCycleToggle">\n                    <span style="font-size: 0.75rem; color: rgba(255,255,255,0.7);">Auto Cycle</span>\n                    <div class="toggle-switch" id="toggleSwitch">\n                        <div class="toggle-slider"></div>\n                    </div>\n                </div>\n            </div>\n\n            <div class="ambient-status" id="ambientStatus">\n                <span class="ambient-icon">🎵</span>\n                <span id="ambientText">Ambient sounds active</span>\n            </div>\n        '),this.bindControlEvents()}bindControlEvents(){document.querySelectorAll(".time-btn").forEach(t=>{t.addEventListener("click",()=>{const e=t.dataset.time;this.setTime(e),this.updateActiveButton(".time-btn",t)})}),document.querySelectorAll(".weather-type-btn").forEach(t=>{t.addEventListener("click",()=>{const e=t.dataset.weather;this.setWeather(e),this.updateActiveButton(".weather-type-btn",t)})});const t=document.getElementById("autoCycleToggle"),e=document.getElementById("toggleSwitch");t.addEventListener("click",()=>{this.autoCycle=!this.autoCycle,e.classList.toggle("active",this.autoCycle),this.autoCycle?this.startAutoCycle():this.stopAutoCycle()})}updateActiveButton(t,e){document.querySelectorAll(t).forEach(t=>t.classList.remove("active")),e.classList.add("active")}setTime(t){const e=document.getElementById("mapContainer");e.classList.remove("time-dawn","time-day","time-dusk","time-night"),e.classList.add(`time-${t}`),this.currentTime=t,console.log(`⏰ Time set to: ${t}`),this.updateAmbientStatus()}setWeather(t){const e=document.getElementById("mapContainer");e.classList.remove("weather-clear","weather-rain","weather-snow","weather-fog"),"clear"!==t&&e.classList.add(`weather-${t}`),this.currentWeather=t,console.log(`🌤️ Weather set to: ${t}`),this.updateAmbientStatus()}setTimeFromRealWorld(){const t=(new Date).getHours();t>=5&&t<8?this.setTime("dawn"):t>=8&&t<17?this.setTime("day"):t>=17&&t<20?this.setTime("dusk"):this.setTime("night");const e=document.querySelector(`.time-btn[data-time="${this.currentTime}"]`);e&&this.updateActiveButton(".time-btn",e)}startAutoCycle(){const t=["dawn","day","dusk","night"];let e=t.indexOf(this.currentTime);this.cycleInterval=setInterval(()=>{e=(e+1)%t.length,this.setTime(t[e]);const n=document.querySelector(`.time-btn[data-time="${t[e]}"]`);if(n&&this.updateActiveButton(".time-btn",n),Math.random()<.3){const t=["clear","rain","snow","fog"],e=t[Math.floor(Math.random()*t.length)];this.setWeather(e);const n=document.querySelector(`.weather-type-btn[data-weather="${e}"]`);n&&this.updateActiveButton(".weather-type-btn",n)}},3e4),console.log("🔄 Auto-cycle started")}stopAutoCycle(){this.cycleInterval&&(clearInterval(this.cycleInterval),this.cycleInterval=null),console.log("⏸️ Auto-cycle stopped")}generateStars(){const t=document.querySelector(".stars-container");if(!t)return;for(let e=0;e<this.particleCount.stars;e++){const e=document.createElement("div"),n=Math.random();let a="";n>.9?a="bright":n>.8?a="blue":n>.7&&(a="gold"),e.className=`star ${a}`.trim(),e.style.left=100*Math.random()+"%",e.style.top=55*Math.random()+"%",e.style.animationDelay=3*Math.random()+"s",e.style.animationDuration=2+3*Math.random()+"s",t.appendChild(e)}}generateRain(){const t=document.querySelector(".rain-container");if(t)for(let e=0;e<this.particleCount.rain;e++){const e=document.createElement("div");e.className="rain-drop",e.style.left=100*Math.random()+"%",e.style.animationDuration=.5+.5*Math.random()+"s",e.style.animationDelay=2*Math.random()+"s",t.appendChild(e)}}generateSnow(){const t=document.querySelector(".snow-container");if(t)for(let e=0;e<this.particleCount.snow;e++){const e=document.createElement("div");e.className="snowflake",e.style.left=100*Math.random()+"%",e.style.width=4+6*Math.random()+"px",e.style.height=e.style.width,e.style.animationDuration=3+4*Math.random()+"s",e.style.animationDelay=5*Math.random()+"s",t.appendChild(e)}}updateAmbientStatus(){const t=document.getElementById("ambientText");if(!t)return;t.textContent=`${{dawn:"🌅",day:"☀️",dusk:"🌇",night:"🌙"}[this.currentTime]} ${this.currentTime.charAt(0).toUpperCase()+this.currentTime.slice(1)} · ${{clear:"☀️",rain:"🌧️",snow:"❄️",fog:"🌫️"}[this.currentWeather]} ${this.currentWeather.charAt(0).toUpperCase()+this.currentWeather.slice(1)}`}}let weatherSystem;"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>{weatherSystem=new WeatherSystem}):weatherSystem=new WeatherSystem;